{'command': 'python3 -c "
import json
d=json.load(open('/tmp/row133.json'))
msgs=d['rows'][0]['row']['messages']
out=open('filtered.txt','w')
for i,m in enumerate(msgs):
    ts=m['timestamp'][11:19]
    if m['role']=='user':
        c=m['content']
        if c.startswith('<task-notification>'):
            # extract summary line
            import re
            s=re.search(r'<summary>(.*?)</summary>',c,re.S)
            out.write(f'\n## [{i}] USER {ts} TASK-NOTIFICATION: {s.group(1) if s else \"\"} (len={len(c)})\n')
            # include first 600 chars of result for background command outputs
            if 'Background command' in c:
                r=re.search(r'<result>(.*?)</result>',c,re.S)
                if r: out.write('  RESULT: '+r.group(1)[:900].replace(chr(10),' | ')+'\n')
        elif 'This session is being continued' in c:
            out.write(f'\n## [{i}] USER {ts} COMPACTION SUMMARY (len={len(c)})\n')
        else:
            out.write(f'\n## [{i}] USER {ts}\n{c}\n')
        continue
    out.write(f'\n## [{i}] A {ts}\n')
    if m.get('thinking'):
        t=m['thinking']
        out.write('  [THINK] '+t[:700].replace(chr(10),' ')+('...' if len(t)>700 else '')+'\n')
    if m.get('content'):
        out.write(m['content'][:2500]+'\n')
    if m.get('tool_uses'):
        for t in m['tool_uses']:
            inp=t.get('input'); s=json.dumps(inp) if not isinstance(inp,str) else inp
            out.write(f'  [TOOL {t.get(\"tool\")}] '+s[:400].replace(chr(10),' ')+'\n')
out.close()
